import { AlertTriangle, Thermometer, FlaskConical, CheckCircle } from "lucide-react";
import { LOTES_DEMO, RANGOS, fmtFechaHora } from "../utils/constants";

export default function Alertas() {
  const alertas = LOTES_DEMO.filter(l => !l.apta);
  return (
    <div style={{ padding:"28px 32px", display:"flex", flexDirection:"column", gap:22 }} className="fade-up">
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between" }}>
        <h1 style={{ fontFamily:"'Playfair Display',serif", fontSize:38, fontWeight:800, letterSpacing:"-0.02em" }}>Alertas.</h1>
        {alertas.length > 0 && (
          <span style={{ background:"rgba(231,76,60,0.15)", border:"1px solid rgba(231,76,60,0.35)", borderRadius:999, padding:"6px 16px", fontSize:12, fontWeight:700, color:"#e74c3c", display:"flex", alignItems:"center", gap:8 }}>
            <AlertTriangle size={13}/> {alertas.length} alerta{alertas.length > 1 ? "s" : ""} activa{alertas.length > 1 ? "s" : ""}
          </span>
        )}
      </div>
      {alertas.length === 0 ? (
        <div className="navy-card" style={{ padding:"64px", display:"flex", flexDirection:"column", alignItems:"center", gap:12, color:"#2ecc71" }}>
          <CheckCircle size={48}/>
          <p style={{ fontFamily:"'Playfair Display',serif", fontSize:20, fontWeight:700 }}>Sin alertas activas</p>
          <p style={{ fontSize:13, color:"rgba(255,255,255,0.45)" }}>Todos los lotes recientes están dentro del rango aceptable.</p>
        </div>
      ) : (
        <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
          {alertas.map((l, i) => {
            const errores = [];
            if (l.temp < RANGOS.temperatura.min || l.temp > RANGOS.temperatura.max)
              errores.push({ icon:Thermometer, color:"#6a9fd8", msg:`Temperatura: ${l.temp}°C (máx ${RANGOS.temperatura.max}°C)` });
            if (l.ph < RANGOS.ph.min || l.ph > RANGOS.ph.max)
              errores.push({ icon:FlaskConical, color:"#a8c8ec", msg:`pH: ${l.ph} (rango ${RANGOS.ph.min}–${RANGOS.ph.max})` });
            return (
              <div key={i} className="navy-card" style={{ padding:"20px", borderLeft:"3px solid #e74c3c" }}>
                <div style={{ display:"flex", alignItems:"flex-start", justifyContent:"space-between", gap:12, marginBottom:12 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:14 }}>
                    <div style={{ width:38, height:38, borderRadius:10, background:"rgba(231,76,60,0.15)", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>
                      <AlertTriangle size={18} color="#e74c3c"/>
                    </div>
                    <div>
                      <p style={{ fontWeight:700, fontSize:14 }}>{l.finca}</p>
                      <p style={{ fontSize:12, color:"rgba(255,255,255,0.45)" }}>Lote {l.id} · {l.operador} · {l.litros.toLocaleString()} L</p>
                    </div>
                  </div>
                  <span style={{ fontSize:11, color:"rgba(255,255,255,0.35)", whiteSpace:"nowrap", flexShrink:0 }}>
                    {fmtFechaHora(l.fecha)}
                  </span>
                </div>
                <div style={{ display:"flex", flexDirection:"column", gap:6, paddingLeft:52 }}>
                  {errores.map(({ icon:Icon, color, msg }, j) => (
                    <div key={j} style={{ display:"flex", alignItems:"center", gap:8, fontSize:12, color:"#fca5a5" }}>
                      <Icon size={13} color={color}/> {msg}
                    </div>
                  ))}
                  {l.obs && <p style={{ fontSize:12, color:"rgba(255,255,255,0.35)", marginTop:2 }}>Obs: {l.obs}</p>}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
